/* ---------------- func_00029C00 (src/pilot/func_00029C00.c) ---------------- */
/* unknown Driver 2 counterpart: per-player trail/skid ring buffer update */
void func_00029C00(int player)
{
    VECTOR v[4];
    VECTOR pos;
    VECTOR vel;
    char pad[16];
    short surf[4];
    VECTOR *a;
    VECTOR *b;
    TYRE_TRACK *t;
    int idx;
    int angle;
    int c, s;
    int dx, dz;

    idx = D_000A5D7C[player] + D_000A1CCC[player];
    a = &D_000A20DC[player];
    b = &D_000A211C[player];
    if (idx >= 64)
        idx -= 64;
    t = &track_buffer[player][idx];

    if (ROADS_GetRouteData(b->vx, b->vz, surf) != 0) {
        if (modelpointers[surf[0]][0] & 0x80)
            return;
        if (modelpointers[surf[0]][1] & 0x4000) {
            t->surface = 2;
            D_00097028.v = 1;
        } else
            t->surface = 1;
    } else
        t->surface = 1;

    pos.vx = b->vx;
    pos.vy = -b->vy - 50;
    pos.vz = b->vz;

    if ((D_000A294C[player]++ & 3) == 1) {
        GetSmokeDrift(&vel);
        if (t->surface == 2) {
            VECTOR v2 = {0, 50, 0};
            Setup_Smoke(&pos, 100, 500, 3, 0, &vel, 0);
            func_00047FA4(&pos, &v2, 5, 2);
        } else if (*(int *)&wetness == 0) {
            Setup_Smoke(&pos, 100, 500, 2, 0, &vel, 0);
        }
    }

    dx = a->vx - b->vx;
    dz = a->vz - b->vz;
    angle = -ratan2(dz, dx) & 0xfff;
    c = (D_0008EAAA[angle * 2] * 40) / 4096;
    s = (D_0008EAAA[angle * 2 - 1] * 40) / 4096;

    v[1].vx = v[0].vx = a->vx;
    v[1].vy = v[0].vy = a->vy - 10;
    v[1].vz = v[0].vz = a->vz;
    v[3].vx = v[2].vx = b->vx;
    v[3].vy = v[2].vy = b->vy - 10;
    v[3].vz = v[2].vz = b->vz;
    v[0].vx += s;
    v[0].vz += c;
    v[2].vx += s;
    v[2].vz += c;

    if (D_000A1CCC[player] != 64)
        D_000A1CCC[player]++;
    else {
        if (++D_000A5D7C[player] >= 64)
            D_000A5D7C[player] -= 64;
    }

    if (D_000A1C08[player] == 1 && D_0009701C.v == 1)
        t->type = 1;
    else
        t->type = 0;

    t->p1.vx = v[0].vx;
    t->p1.vy = v[0].vy;
    t->p1.vz = v[0].vz;
    t->p2.vx = v[1].vx;
    t->p2.vy = v[1].vy;
    t->p2.vz = v[1].vz;
    t->p3.vx = v[2].vx;
    t->p3.vy = v[2].vy;
    t->p3.vz = v[2].vz;
    t->p4.vx = v[3].vx;
    t->p4.vy = v[3].vy;
    t->p4.vz = v[3].vz;
    D_000A1C08[player] = 1;
}

/* ---------------- DrawTyreTracks (src/pilot/DrawTyreTracks.c) ---------------- */
/* DrawTyreTracks (Driver 2 name) */
extern int current;
#define current (*(DB **)&current)
#define gte_SetTransVector(r0) __asm__ volatile ( \
    "lw    $12, 0( %0 );" "lw    $13, 4( %0 );" "lw    $14, 8( %0 );" \
    "ctc2  $12, $5;" "ctc2  $13, $6;" "ctc2  $14, $7" : : "r"(r0) : "$12", "$13", "$14")
#define gte_ldv3c(r0) __asm__ volatile ( \
    "lwc2  $0, 0( %0 );" "lwc2  $1, 4( %0 );" "lwc2  $2, 8( %0 );" \
    "lwc2  $3, 12( %0 );" "lwc2  $4, 16( %0 );" "lwc2  $5, 20( %0 )" : : "r"(r0))
#define gte_rtpt() __asm__ volatile ("nop;" "nop;" "rtpt")
#define gte_rtps() __asm__ volatile ("nop;" "nop;" "rtps")
#define gte_stsxy(r0) __asm__ volatile ("swc2  $14, 0( %0 )" : : "r"(r0) : "memory")
#define gte_stsxy3(r0, r1, r2) __asm__ volatile ( \
    "swc2  $12, 0( %0 );" "swc2  $13, 0( %1 );" "swc2  $14, 0( %2 )" : : "r"(r0), "r"(r1), "r"(r2) : "memory")
void DrawTyreTracks(void)
{
    VECTOR p[4];
    SVECTOR ps[4];
    int z;
    TYRE_TRACK *tt_p;
    int index, loop;
    int wheel_loop;
    unsigned char last_duff;
    POLY_FT4 *poly;
    POLY_FT4 *lasttyre;
    int t;

    gte_SetRotMatrix(&inv_camera_matrix);
    gte_SetTransVector(&D_0008909C);

    for (wheel_loop = 0; wheel_loop < 4; wheel_loop++) {
        if (D_000A1CCC[wheel_loop] == 0)
            continue;
        lasttyre = 0;
        last_duff = 1;
        index = D_000A5D7C[wheel_loop];

        for (loop = 0; loop < D_000A1CCC[wheel_loop]; loop++) {
            tt_p = &track_buffer[wheel_loop][index];
            index++;
            if (index == 64)
                index = 0;

            if (lasttyre == 0 || tt_p->type == 0 || last_duff) {
                last_duff = 1;
                t = tt_p->p1.vx - camera_position.vx;
                if (t < -9000 || t > 9000)
                    continue;
                ps[0].vx = t;
                t = tt_p->p1.vz - camera_position.vz;
                if (t < -9000 || t > 9000)
                    continue;
                ps[0].vz = t;
                ps[0].vy = -tt_p->p1.vy - camera_position.vy;
                ps[2].vx = tt_p->p3.vx - camera_position.vx;
                ps[2].vz = tt_p->p3.vz - camera_position.vz;
                ps[2].vy = -tt_p->p3.vy - camera_position.vy;
                ps[1].vx = tt_p->p2.vx - camera_position.vx;
                ps[1].vy = -tt_p->p2.vy - camera_position.vy;
                ps[1].vz = tt_p->p2.vz - camera_position.vz;
                poly = (POLY_FT4 *)current->primptr;
                gte_ldv3c(&ps[0]);
                gte_rtpt();
                ps[3].vx = tt_p->p4.vx - camera_position.vx;
                ps[3].vy = -tt_p->p4.vy - camera_position.vy;
                ps[3].vz = tt_p->p4.vz - camera_position.vz;
                gte_stsxy3(&poly->x0, &poly->x1, &poly->x2);
                gte_stsz(&z);
                gte_ldv0(&ps[3]);
                gte_rtps();
                gte_stsxy(&poly->x3);
                if (z <= 50)
                    continue;
                last_duff = 0;
            } else {
                poly = (POLY_FT4 *)current->primptr;
                last_duff = 1;
                t = tt_p->p3.vx - camera_position.vx;
                if (t < -9000 || t > 9000)
                    continue;
                ps[2].vx = t;
                t = tt_p->p3.vz - camera_position.vz;
                if (t < -9000 || t > 9000)
                    continue;
                ps[2].vz = t;
                ps[2].vy = -tt_p->p3.vy - camera_position.vy;
                gte_ldv0(&ps[2]);
                gte_rtps();
                ps[3].vx = tt_p->p4.vx - camera_position.vx;
                ps[3].vy = -tt_p->p4.vy - camera_position.vy;
                ps[3].vz = tt_p->p4.vz - camera_position.vz;
                gte_stsxy(&poly->x2);
                gte_stsz(&z);
                gte_ldv0(&ps[3]);
                gte_rtps();
                if (z <= 50)
                    continue;
                *(unsigned int *)&poly->x0 = *(unsigned int *)&lasttyre->x2;
                *(unsigned int *)&poly->x1 = *(unsigned int *)&lasttyre->x3;
                last_duff = 0;
                gte_stsxy(&poly->x3);
            }

            ((unsigned char *)poly)[3] = 9;
            poly->code = 0x2C;

            if (tt_p->surface == 1) {
                poly->r0 = 26;
                poly->g0 = 26;
                poly->b0 = 26;
            } else {
                poly->r0 = 17;
                poly->g0 = 35;
                poly->b0 = 35;
            }

            poly->u0 = D_000BBE44.coords.u0;
            poly->v0 = D_000BBE44.coords.v0;
            poly->u1 = D_000BBE44.coords.u1;
            poly->v1 = D_000BBE44.coords.v1;
            poly->u2 = D_000BBE44.coords.u2;
            poly->v2 = D_000BBE44.coords.v2;
            poly->u3 = D_000BBE44.coords.u3;
            poly->v3 = D_000BBE44.coords.v3;
            *(unsigned short *)((char *)poly + 0x16) = D_000BBE44.tpageid | 0x40;
            *(unsigned short *)((char *)poly + 0xE) = D_000BBE44.clutid;
            poly->code |= 2;

            ((P_TAG *)poly)->addr = ((P_TAG *)&current->ot[z >> 3])->addr;
            ((P_TAG *)&current->ot[z >> 3])->addr = (unsigned int)poly;
            current->primptr += 0x28;

            lasttyre = poly;
        }
    }
}
#undef current
#undef gte_SetTransVector
#undef gte_ldv3c
#undef gte_rtps
#undef gte_rtpt
#undef gte_stsxy
#undef gte_stsxy3

