#define addPrim(ot, p) (((P_TAG *)(p))->addr = ((P_TAG *)(ot))->addr, ((P_TAG *)(ot))->addr = (unsigned long)(p))
void SubdivShadow(int z0, int z1, int z2, int z3, FT4 *sps)
{
    FT4 *spd;
    DB *db;
    int i;

    spd = (FT4 *)current->primptr;
    current->primptr += sizeof(FT4) * 8;

    spd[0].tag = spd[1].tag = spd[2].tag = spd[3].tag =
        spd[4].tag = spd[5].tag = spd[6].tag = spd[7].tag = sps->tag;
    spd[0].rgbc = spd[1].rgbc = spd[2].rgbc = spd[3].rgbc =
        spd[4].rgbc = spd[5].rgbc = spd[6].rgbc = spd[7].rgbc = sps->rgbc;

    for (i = 0; i < 8; i++) {
        *(unsigned long *)&spd[i].uv0 = *(unsigned long *)&sps->uv0;
        *(unsigned long *)&spd[i].uv1 = *(unsigned long *)&sps->uv1;
        *(unsigned long *)&spd[i].uv2 = *(unsigned long *)&sps->uv2;
        *(unsigned long *)&spd[i].uv3 = *(unsigned long *)&sps->uv3;
    }

    {
        unsigned long A0, A1, E0, E1, C0, C1, B0, B1, D0, D1;

        i = 0x08000800; /* bias so packed x/y halves average without borrow */
        A0 = sps->xy0 + i;
        A1 = sps->xy1 + i;
        E0 = sps->xy2 + i;
        E1 = sps->xy3 + i;
        C0 = ((A0 + E0) >> 1);
        B0 = (A0 + C0) >> 1;
        C1 = ((A1 + E1) >> 1);
        B1 = (A1 + C1) >> 1;
        D0 = (E0 + C0) >> 1;
        D1 = (E1 + C1) >> 1;
        spd[0].xy0 = (A0) - i;
        spd[0].xy1 = ((A0 + A1) >> 1) - i;
        spd[4].xy0 = ((A0 + A1) >> 1) - i;
        spd[4].xy1 = (A1) - i;
        spd[0].xy2 = (B0) - i;
        spd[0].xy3 = ((B0 + B1) >> 1) - i;
        spd[4].xy2 = ((B0 + B1) >> 1) - i;
        spd[4].xy3 = (B1) - i;
        spd[1].xy0 = (B0) - i;
        spd[1].xy1 = ((B0 + B1) >> 1) - i;
        spd[5].xy0 = ((B0 + B1) >> 1) - i;
        spd[5].xy1 = (B1) - i;
        spd[1].xy2 = (C0) - i;
        spd[1].xy3 = ((C0 + C1) >> 1) - i;
        spd[5].xy2 = ((C0 + C1) >> 1) - i;
        spd[5].xy3 = (C1) - i;
        spd[2].xy0 = (C0) - i;
        spd[2].xy1 = ((C0 + C1) >> 1) - i;
        spd[6].xy0 = ((C0 + C1) >> 1) - i;
        spd[6].xy1 = (C1) - i;
        spd[2].xy2 = (D0) - i;
        spd[2].xy3 = ((D0 + D1) >> 1) - i;
        spd[6].xy2 = ((D0 + D1) >> 1) - i;
        spd[6].xy3 = (D1) - i;
        spd[3].xy0 = (D0) - i;
        spd[3].xy1 = ((D0 + D1) >> 1) - i;
        spd[7].xy0 = ((D0 + D1) >> 1) - i;
        spd[7].xy1 = (D1) - i;
        spd[3].xy2 = (E0) - i;
        spd[3].xy3 = ((E0 + E1) >> 1) - i;
        spd[7].xy2 = ((E0 + E1) >> 1) - i;
        spd[7].xy3 = (E1) - i;
    }
    {
        unsigned long A0, A1, E0, E1, C0, C1, B0, B1, D0, D1;

        A0 = sps->uv0 & 0xFEFF;
        A1 = sps->uv1 & 0xFEFF;
        E0 = sps->uv2 & 0xFEFF;
        E1 = sps->uv3 & 0xFEFF;
        C0 = ((A0 + E0) >> 1) & 0xFEFF;
        B0 = (A0 + C0) >> 1;
        C1 = ((A1 + E1) >> 1) & 0xFEFF;
        B1 = (A1 + C1) >> 1;
        D0 = (E0 + C0) >> 1;
        D1 = (E1 + C1) >> 1;
        spd[0].uv0 = A0;
        spd[0].uv1 = (A0 + A1) >> 1;
        spd[4].uv0 = (A0 + A1) >> 1;
        spd[4].uv1 = A1;
        spd[0].uv2 = B0;
        spd[0].uv3 = (B0 + B1) >> 1;
        spd[4].uv2 = (B0 + B1) >> 1;
        spd[4].uv3 = B1;
        spd[1].uv0 = B0;
        spd[1].uv1 = (B0 + B1) >> 1;
        spd[5].uv0 = (B0 + B1) >> 1;
        spd[5].uv1 = B1;
        spd[1].uv2 = C0;
        spd[1].uv3 = (C0 + C1) >> 1;
        spd[5].uv2 = (C0 + C1) >> 1;
        spd[5].uv3 = C1;
        spd[2].uv0 = C0;
        spd[2].uv1 = (C0 + C1) >> 1;
        spd[6].uv0 = (C0 + C1) >> 1;
        spd[6].uv1 = C1;
        spd[2].uv2 = D0;
        spd[2].uv3 = (D0 + D1) >> 1;
        spd[6].uv2 = (D0 + D1) >> 1;
        spd[6].uv3 = D1;
        spd[3].uv0 = D0;
        spd[3].uv1 = (D0 + D1) >> 1;
        spd[7].uv0 = (D0 + D1) >> 1;
        spd[7].uv1 = D1;
        spd[3].uv2 = E0;
        spd[3].uv3 = (E0 + E1) >> 1;
        spd[7].uv2 = (E0 + E1) >> 1;
        spd[7].uv3 = E1;
    }

    db = current;
    addPrim(db->ot + ((z0 * 7 + z3) >> 6), &spd[0]);
    addPrim(db->ot + ((z0 * 5 + z3 * 3) >> 6), &spd[1]);
    addPrim(db->ot + ((z0 * 3 + z3 * 5) >> 6), &spd[2]);
    addPrim(db->ot + ((z0 + z3 * 7) >> 6), &spd[3]);
    addPrim(db->ot + ((z1 * 7 + z2) >> 6), &spd[4]);
    addPrim(db->ot + ((z1 * 5 + z2 * 3) >> 6), &spd[5]);
    addPrim(db->ot + ((z1 * 3 + z2 * 5) >> 6), &spd[6]);
    addPrim(db->ot + ((z1 + z2 * 7) >> 6), &spd[7]);
}
#undef addPrim
#undef current

/* ---------------- PlaceShadowForCar (src/pilot/PlaceShadowForCar.c) ---------------- */
/* Driver 2: PlaceShadowForCar (SHADOW.C) */
extern int current;
#define current (*(DB **)&current)
#define gte_stsxy3(r0, r1, r2) __asm__ volatile ( \
    "swc2  $12, 0( %0 );" "swc2  $13, 0( %1 );" "swc2  $14, 0( %2 )" : : "r"(r0), "r"(r1), "r"(r2) : "memory")
#define gte_stsxy(r0) __asm__ volatile ("swc2  $14, 0( %0 )" : : "r"(r0) : "memory")
#define gte_stsz3(r0, r1, r2) __asm__ volatile ( \
    "swc2  $17, 0( %0 );" "swc2  $18, 0( %1 );" "swc2  $19, 0( %2 )" : : "r"(r0), "r"(r1), "r"(r2) : "memory")
#define gte_ldv3c(r0) __asm__ volatile ( \
    "lwc2  $0, 0( %0 );" "lwc2  $1, 4( %0 );" "lwc2  $2, 8( %0 );" \
    "lwc2  $3, 12( %0 );" "lwc2  $4, 16( %0 );" "lwc2  $5, 20( %0 )" : : "r"(r0))
#define gte_rtpt() __asm__ volatile ("nop;" "nop;" "rtpt")
#define gte_rtps() __asm__ volatile ("nop;" "nop;" "rtps")
#define setaddr(_p, _addr) (((P_TAG *)(_p))->addr = (unsigned long)(_addr))
#define getaddr(_p) (unsigned long)(((P_TAG *)(_p))->addr)
#define addPrim(ot, p) setaddr(p, getaddr(ot)), setaddr(ot, p)
#define sp (cp->shadowPoints)
void PlaceShadowForCar(int slot)
{
    SVECTOR points[4];
    int z0, z1, z2, z3;
    int z;
    CAR_DATA *cp;
    POLY_FT4 *spt;

    if (slot == 0 && *(int *)&D_00096874 == 1)
        return;

    cp = &car_data[slot];

    points[0].vx = sp[0].vx - camera_position.vx;
    points[0].vy = -sp[0].vy - camera_position.vy;
    points[0].vz = sp[0].vz - camera_position.vz;
    points[1].vx = sp[1].vx - camera_position.vx;
    points[1].vy = -sp[1].vy - camera_position.vy;
    points[1].vz = sp[1].vz - camera_position.vz;
    points[2].vx = sp[3].vx - camera_position.vx;
    points[2].vy = -sp[3].vy - camera_position.vy;
    points[2].vz = sp[3].vz - camera_position.vz;

    gte_SetTransVec0(&D_0008909C);
    gte_SetRotMatrix(&inv_camera_matrix);

    spt = &D_000A216C[current->id][slot];

    gte_ldv3c(&points[0]);
    gte_rtpt();

    points[3].vx = sp[2].vx - camera_position.vx;
    points[3].vy = -sp[2].vy - camera_position.vy;
    points[3].vz = sp[2].vz - camera_position.vz;

    gte_stsxy3(&spt->x0, &spt->x1, &spt->x3);
    gte_stsz3(&z0, &z1, &z2);
    z = z0;
    gte_ldv0(&points[3]);
    gte_rtps();
    if (z < z1)
        z = z1;
    if (z < z2)
        z = z2;
    gte_stsz(&z3);
    gte_stsxy(&spt->x2);
    if (z < z3)
        z = z3;

    if ((*(int *)&D_00096834 == 1 || *(int *)&D_00096834 == 5)
        && ((sp[0].vy | sp[1].vy | sp[2].vy | sp[3].vy) & 1)) {
        if (z0 < z1)
            z0 = (z0 + z1) / 2;
        else
            z1 = (z0 + z1) / 2;
        if (z2 < z3)
            z2 = (z2 + z3) / 2;
        else
            z3 = (z2 + z3) / 2;

        if (z0 > 28) z0 -= 20; else z0 = 8;
        if (z1 > 28) z1 -= 20; else z1 = 8;
        if (z2 > 28) z2 -= 20; else z2 = 8;
        if (z3 > 28) z3 -= 20; else z3 = 8;

        SubdivShadow(z0, z1, z2, z3, spt);
        return;
    }

    addPrim(current->ot + (z >> 3), spt);
}
#undef addPrim
#undef current
#undef getaddr
#undef gte_ldv3c
#undef gte_rtps
#undef gte_rtpt
#undef gte_stsxy
#undef gte_stsxy3
#undef gte_stsz3
#undef setaddr
#undef sp

/* ---------------- clipAgainstZ (src/pilot/clipAgainstZ.c) ---------------- */
/* clipAgainstZ: clipAgainstZ (Driver 2, SHADOW.C) */
/* cv */
/* lastcv */
/* numcv */
void clipAgainstZ(void)
{
    SVECTOR *curr;
    SVECTOR *prev;
    SVECTOR *dst;
    int flags;
    int srccount;
    int dstcount;
    int q;
    int pz;
    int d;

    dstcount = 0;
    curr = D_000A1C58 + D_00097170;
    srccount = D_00097160;
    prev = curr - srccount + 1;
    dst = curr + 2;
    flags = (prev->vz > 0) << 1;
    for (srccount--; srccount >= 0; srccount--) {
        q = curr->vz;
        flags >>= 1;
        if (q > 0)
            flags |= 2;
        switch (flags) {
        case 0:
            break;
        case 2:
            pz = prev->vz;
            d = pz - q;
            dst->vx = (curr->vx * pz - prev->vx * q) / d;
            dst->vy = (curr->vy * pz - prev->vy * q) / d;
            dst->pad = (curr->pad * pz - prev->pad * q) / d;
            dst->vz = 0;
            dst--;
            *dst = *curr;
            dst--;
            dstcount += 2;
            break;
        case 1:
            pz = prev->vz;
            d = pz - q;
            dst->vx = (curr->vx * pz - prev->vx * q) / d;
            dst->vy = (curr->vy * pz - prev->vy * q) / d;
            dst->pad = (curr->pad * pz - prev->pad * q) / d;
            dst->vz = 0;
            dst--;
            dstcount++;
            break;
        default:
            *dst = *curr;
            dst--;
            dstcount++;
            break;
        }
        prev = curr;
        curr--;
    }
    D_00097160 = dstcount;
    D_00097170 += 2;
}

